messages.content:
{
  "type": "array",
  "items": {
    "anyOf": [
      {
        "type": "string",
        "description": "Plain text content."
      },
      {
        "type": "array",
        "items": {
          "$ref": "RichContentPart",
          "description": "A rich content part."
        },
        "description": "An array of rich content parts."
      }
    ],
    "description": "A possible assistant response. The LLMs in the Ensemble may vote for this option."
  },
  "description": "A list of possible assistant responses which the LLMs in the Ensemble will vote on. The output scores will be of the same length, each corresponding to one response. The winner is the response with the highest score."
}

{
  "anyOf": [
    {
      "$ref": "DeveloperMessage",
      "description": "Developer-provided instructions that the model should follow, regardless of messages sent by the user."
    },
    {
      "$ref": "SystemMessage",
      "description": "Developer-provided instructions that the model should follow, regardless of messages sent by the user."
    },
    {
      "$ref": "UserMessage",
      "description": "Messages sent by an end user, containing prompts or additional context information."
    },
    {
      "$ref": "ToolMessage",
      "description": "Messages sent by tools in response to tool calls made by the assistant."
    },
    {
      "$ref": "AssistantMessage",
      "description": "Messages sent by the model in response to user messages."
    }
  ],
  "description": "A message exchanged in a chat conversation."
}

{
  "type": "object",
  "properties": {
    "role": {
      "const": "developer"
    },
    "content": {
      "anyOf": [
        {
          "type": "string",
          "description": "Plain text content."
        },
        {
          "type": "array",
          "items": {
            "$ref": "SimpleContentPart",
            "description": "A simple content part."
          },
          "description": "An array of simple content parts."
        }
      ],
      "description": "Simple content."
    },
    "name": {
      "anyOf": [
        {
          "type": "string",
          "description": "An optional name for the participant. Provides the model information to differentiate between participants of the same role."
        },
        {
          "type": "null"
        }
      ]
    }
  },
  "required": [
    "role",
    "content"
  ],
  "description": "Developer-provided instructions that the model should follow, regardless of messages sent by the user."
}

{
  "type": "object",
  "properties": {
    "type": {
      "const": "file"
    },
    "file": {
      "type": "object",
      "properties": {
        "file_data": {
          "anyOf": [
            {
              "type": "string",
              "description": "The base64 encoded file data, used when passing the file to the model as a string."
            },
            {
              "type": "null"
            }
          ]
        },
        "file_id": {
          "anyOf": [
            {
              "type": "string",
              "description": "The ID of an uploaded file to use as input."
            },
            {
              "type": "null"
            }
          ]
        },
        "filename": {
          "anyOf": [
            {
              "type": "string",
              "description": "The name of the file, used when passing the file to the model as a string."
            },
            {
              "type": "null"
            }
          ]
        },
        "file_url": {
          "anyOf": [
            {
              "type": "string",
              "description": "The URL of the file, used when passing the file to the model as a URL."
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "description": "The file to be used as input, either as base64 data, an uploaded file ID, or a URL."
    }
  },
  "required": [
    "type",
    "file"
  ],
  "description": "A file rich content part."
}
